CREATE VIEW v_race_results AS SELECT results.resultId AS result_id, results.number AS car_number, results.grid, results.position, results.positionOrder AS position_order, results.points, results.laps, results.fastestLap AS fastest_lap, results.fastestLapSpeed AS fastest_lap_speed, drivers.driverId AS driver_id, drivers.driverRef AS driver_ref, drivers.forename AS driver_forename, drivers.surname AS driver_surname, drivers.nationality AS driver_nationality, constructors.constructorId AS constructor_id, constructors.name AS constructor_name, races.raceId AS race_id, races.year AS race_year, races.round AS race_round, races.name AS race_name, races.date AS race_date, status.status AS result_status, results.raceId, results.driverId, results.constructorId, results.positionText, results.time, results.milliseconds, results.rank, results.fastestLapTime, results.statusId, races.circuitId, races.time AS races_time, races.url, drivers.number, drivers.code, drivers.dob, drivers.url AS drivers_url, constructors.constructorRef, constructors.nationality, constructors.url AS constructors_url, status.statusId AS status_statusId FROM results LEFT JOIN races ON results.raceId = races.raceId LEFT JOIN drivers ON results.driverId = drivers.driverId LEFT JOIN constructors ON results.constructorId = constructors.constructorId LEFT JOIN status ON results.statusId = status.statusId;

CREATE VIEW v_race_circuits AS SELECT races.raceId AS race_id, races.year AS race_year, races.round AS race_round, races.name AS race_name, races.date AS race_date, circuits.circuitId AS circuit_id, circuits.circuitRef AS circuit_ref, circuits.name AS circuit_name, circuits.location AS circuit_location, circuits.country AS circuit_country, races.circuitId, races.time, races.url, circuits.lat, circuits.lng, circuits.alt, circuits.url AS circuits_url FROM races LEFT JOIN circuits ON races.circuitId = circuits.circuitId;

CREATE VIEW v_qualifying_driver AS SELECT qualifying.qualifyId AS qualify_id, qualifying.position AS qualify_position, qualifying.q1, qualifying.q2, qualifying.q3, drivers.driverId AS driver_id, drivers.forename AS driver_forename, drivers.surname AS driver_surname, constructors.name AS constructor_name, races.raceId AS race_id, races.name AS race_name, races.year AS race_year, qualifying.raceId, qualifying.driverId, qualifying.constructorId, qualifying.number, drivers.driverRef, drivers.number AS drivers_number, drivers.code, drivers.dob, drivers.nationality, drivers.url, races.round, races.circuitId, races.date, races.time, races.url AS races_url, constructors.constructorId AS constructors_constructorId, constructors.constructorRef, constructors.nationality AS constructors_nationality, constructors.url AS constructors_url FROM qualifying LEFT JOIN drivers ON qualifying.driverId = drivers.driverId LEFT JOIN races ON qualifying.raceId = races.raceId LEFT JOIN constructors ON qualifying.constructorId = constructors.constructorId;

CREATE VIEW v_seasons AS SELECT seasons.year, seasons.url FROM seasons;

CREATE VIEW v_constructorresults AS SELECT constructorResults.constructorResultsId, constructorResults.raceId, constructorResults.constructorId, constructorResults.points, constructorResults.status, constructors.constructorId AS constructors_constructorId, constructors.constructorRef, constructors.name, constructors.nationality, constructors.url, races.raceId AS races_raceId, races.year, races.round, races.circuitId, races.name AS races_name, races.date, races.time, races.url AS races_url FROM constructorResults LEFT JOIN constructors ON constructorResults.constructorId = constructors.constructorId LEFT JOIN races ON constructorResults.raceId = races.raceId;

CREATE VIEW v_constructorstandings AS SELECT constructorStandings.constructorStandingsId, constructorStandings.raceId, constructorStandings.constructorId, constructorStandings.points, constructorStandings.position, constructorStandings.positionText, constructorStandings.wins, constructors.constructorId AS constructors_constructorId, constructors.constructorRef, constructors.name, constructors.nationality, constructors.url, races.raceId AS races_raceId, races.year, races.round, races.circuitId, races.name AS races_name, races.date, races.time, races.url AS races_url FROM constructorStandings LEFT JOIN constructors ON constructorStandings.constructorId = constructors.constructorId LEFT JOIN races ON constructorStandings.raceId = races.raceId;

CREATE VIEW v_driverstandings AS SELECT driverStandings.driverStandingsId, driverStandings.raceId, driverStandings.driverId, driverStandings.points, driverStandings.position, driverStandings.positionText, driverStandings.wins, drivers.driverId AS drivers_driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, races.raceId AS races_raceId, races.year, races.round, races.circuitId, races.name, races.date, races.time, races.url AS races_url FROM driverStandings LEFT JOIN drivers ON driverStandings.driverId = drivers.driverId LEFT JOIN races ON driverStandings.raceId = races.raceId;

CREATE VIEW v_laptimes AS SELECT lapTimes.raceId, lapTimes.driverId, lapTimes.lap, lapTimes.position, lapTimes.time, lapTimes.milliseconds, drivers.driverId AS drivers_driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, races.raceId AS races_raceId, races.year, races.round, races.circuitId, races.name, races.date, races.time AS races_time, races.url AS races_url FROM lapTimes LEFT JOIN drivers ON lapTimes.driverId = drivers.driverId LEFT JOIN races ON lapTimes.raceId = races.raceId;

CREATE VIEW v_pitstops AS SELECT pitStops.raceId, pitStops.driverId, pitStops.stop, pitStops.lap, pitStops.time, pitStops.duration, pitStops.milliseconds, drivers.driverId AS drivers_driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, races.raceId AS races_raceId, races.year, races.round, races.circuitId, races.name, races.date, races.time AS races_time, races.url AS races_url FROM pitStops LEFT JOIN drivers ON pitStops.driverId = drivers.driverId LEFT JOIN races ON pitStops.raceId = races.raceId;
